mapper.select:
SELECT ,
FROM `task` t
WHERE t.id = #{id}

mapper.update:
UPDATE `task`
SET pilot_id   = NULL,
    pilot_name = NULL,
    drone_id   = NULL,
    drone_code = NULL,
    status     = #{newStatus}
WHERE id = #{taskId}
  AND status = #{expectStatus}

UPDATE `task`
SET status          = 'finished',
    actual_end_time = #{actualEndTime}
WHERE id = #{taskId}
  AND status = 'executing'

UPDATE `task`
SET status          = 'failed',
    actual_end_time = #{actualEndTime}
WHERE id = #{taskId}
  AND status = 'executing'

mapper.select:
SELECT 
FROM `task` t
WHERE t.status IN ('dispatched')
  AND t.plan_end_time < #{deadline}
ORDER BY t.id
LIMIT #{limit}

SELECT 
FROM `task` t
WHERE t.pilot_id = #{pilotId}
  AND t.status IN ('dispatched', 'executing')
  AND t.plan_start_time < #{planEndTime}
  AND t.plan_end_time > #{planStartTime}
ORDER BY t.id
LIMIT 1

SELECT 
FROM `task` t
WHERE t.drone_id = #{droneId}
  AND t.status IN ('dispatched', 'executing')
  AND t.plan_start_time < #{planEndTime}
  AND t.plan_end_time > #{planStartTime}
ORDER BY t.id
LIMIT 1

SELECT COUNT(DISTINCT t.pilot_id)
FROM `task` t
WHERE t.status IN ('dispatched', 'executing')
  AND t.pilot_id IS NOT NULL
  AND t.plan_start_time < #{planEndTime}
  AND t.plan_end_time > #{planStartTime}

SELECT COUNT(DISTINCT t.drone_id)
FROM `task` t
WHERE t.status IN ('dispatched', 'executing')
  AND t.drone_id IS NOT NULL
  AND t.plan_start_time < #{planEndTime}
  AND t.plan_end_time > #{planStartTime}

mapper.update:
UPDATE `task`
SET evidence_state = 'confirmed',
    evidence_type  = #{evidenceType},
    evidence_at    = #{evidenceAt}
WHERE id = #{taskId}
  AND evidence_state <> 'confirmed'

mapper.select:
SELECT t.status AS status, COUNT(*) AS cnt FROM `task` t
AND t.pilot_id = #{pilotId}
GROUP BY t.status

SELECT COUNT(*)
FROM `task` t
WHERE t.create_time >= #{from}

    AND t.pilot_id = #{pilotId}

SELECT COUNT(*)
FROM `task` t
WHERE t.status = 'executing'
  AND t.plan_end_time IS NOT NULL
  AND t.plan_end_time < #{now}

    AND t.pilot_id = #{pilotId}
